class Solution {
    public long maxRunTime(int n, int[] batteries) {
        long sum = 0;
        for (int b : batteries) sum += b;

        long left = 1, right = sum / n;
        while (left < right) {
            long mid = (right - left + 1) / 2 + left;
            if (canRun(n, batteries, mid)) {
                left = mid;
            } else {
                right = mid - 1;
            }
        }
        return left;
    }

    private boolean canRun(int n, int[] batteries, long time) {
        long total = 0;
        for (int b : batteries) {
            total += Math.min(b, time);
            if (total >= (long) n * time) return true;
        }
        return false;
    }
}
